#nullable enable // autogenerated

using MVZ2.GameContent.Bosses;
using MVZ2.GameContent.Contraptions;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Pickups;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Localization;
using MVZ2.Vanilla.Pickups;
using MVZ2.Vanilla.Properties;
using MVZ2Logic;
using MVZ2Logic.Blueprints;
using MVZ2Logic.Buffs;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Modifiers;
using PVZEngine.Timing;
using PVZEngine.Tools.Random;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.nitoriGivesLilyPad)]
    public class NitoriGivesLilyPadBuff : BuffDefinition
    {
        public NitoriGivesLilyPadBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new ConveyorPoolPatchArrayModifier(EngineLevelProps.CONVEYOR_POOL_PATCHES, ArrayOperator.Append, PROP_CONVEYOR_POOL_PATCHES));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var level = buff.Level;
            if (level.IsCleared || level.IsAllEnemiesCleared())
            {
                buff.Remove();
                return;
            }
            if (!IsOpen(buff))
            {
                if (level.EntityExists(static e => e.IsEntityOf(VanillaBossID.kraken) && e.GetPhase() >= Kraken.PHASE_2 && e.State == Kraken.STATE_IDLE))
                {
                    SetOpen(buff, true);
                    ShowText(buff);
                }
                SetConveyorPoolPatches(buff, null);
            }
            else
            {
                var timer = GetOrCreateTimer(buff);
                if (timer.RunToExpired())
                {
                    ProduceLilyPad(buff);
                    timer.ResetSeconds(GetDynamicProduceIntervalSeconds(buff));
                }
                SetConveyorPoolPatches(buff, openConveyorPoolPatches);
            }
        }
        public static void ShowText(Buff buff)
        {
            var level = buff.Target as LevelEngine;
            if (level == null)
            {
                return;
            }
            var x = level.GetColumnCenterX(0);
            var z = level.GetLawnCenterZ();
            var y = level.GetGroundY(x, z);
            var position = new Vector3(x, y, z);
            var text = Global.Localization.GetText(VanillaStrings.KRAKEN_NITORIS_SUPPORT);
            var param = new SpawnParams();
            param.SetProperty(FloatingText.PROP_TEXT, text);
            param.SetProperty(EngineEntityProps.MODEL_POSITION_OFFSET, Vector3.back * 5000);
            param.SetProperty(VanillaEntityProps.MAX_TIMEOUT, 180);
            level.SpawnSourced(VanillaEffectID.floatingText, position, new BuffSourceReference(level, buff), param);
        }
        public static void ProduceLilyPad(Buff buff)
        {
            var level = buff.Target as LevelEngine;
            if (level == null)
                return;
            var rng = GetRNG(buff);
            if (rng == null)
            {
                rng = level.CreateRNG();
                SetRNG(buff, rng);
            }
            int minLane = 1;
            int maxLane = level.GetMaxLaneCount() - 1;
            var lane = rng.Next(minLane, maxLane);
            var velocityX = rng.Next(10f, 20f);
            var velocityY = 10f;
            var velocity = new Vector3(velocityX, velocityY, 0);

            var position = level.GetEntityGridPosition(0, lane);
            var param = new SpawnParams();
            param.SetProperty(VanillaPickupProps.CONTENT_ID, LogicBlueprintID.FromEntity(VanillaContraptionID.lilyPad));
            param.EntityVelocity = velocity;
            level.SpawnSourced(VanillaPickupID.blueprintPickup, position, new BuffSourceReference(level, buff), param);
        }
        public static float GetDynamicProduceIntervalSeconds(Buff buff)
        {
            var level = buff.Level;
            var count = level.GetEntityCount(static e => e.IsEntityOf(VanillaContraptionID.lilyPad));
            var t = (float)(count - PRODUCE_LILYPAD_COUNT_MIN) / (PRODUCE_LILYPAD_COUNT_MAX - PRODUCE_LILYPAD_COUNT_MIN);
            return PRODUCE_INTERVAL_SECONDS / Mathf.Lerp(PRODUCE_INTERVAL_SPEED_MIN, PRODUCE_INTERVAL_SPEED_MAX, t);
        }
        public static bool IsOpen(Buff buff) => buff.GetProperty<bool>(PROP_OPEN);
        public static void SetOpen(Buff buff, bool value) => buff.SetProperty(PROP_OPEN, value);
        public static FrameTimer GetOrCreateTimer(Buff buff) => buff.GetOrCreateTimer(PROP_TIMER, Ticks.FromSeconds(GetDynamicProduceIntervalSeconds(buff)));
        public static FrameTimer? GetTimer(Buff buff) => buff.GetProperty<FrameTimer>(PROP_TIMER);
        public static void SetTimer(Buff buff, FrameTimer? value) => buff.SetProperty(PROP_TIMER, value);
        public static RandomGenerator? GetRNG(Buff buff) => buff.GetProperty<RandomGenerator>(PROP_RNG);
        public static void SetRNG(Buff buff, RandomGenerator? value) => buff.SetProperty(PROP_RNG, value);
        public static IConveyorPoolPatch[]? GetConveyorPoolPatches(Buff buff) => buff.GetProperty<IConveyorPoolPatch[]>(PROP_CONVEYOR_POOL_PATCHES);
        public static void SetConveyorPoolPatches(Buff buff, IConveyorPoolPatch[]? value) => buff.SetProperty(PROP_CONVEYOR_POOL_PATCHES, value);
        public const float PRODUCE_INTERVAL_SPEED_MIN = 2f;
        public const float PRODUCE_INTERVAL_SPEED_MAX = 0.5f;
        public const float PRODUCE_INTERVAL_SECONDS = 5f;
        public const int PRODUCE_LILYPAD_COUNT_MIN = 0;
        public const int PRODUCE_LILYPAD_COUNT_MAX = 16;
        public static readonly VanillaBuffPropertyMeta<RandomGenerator> PROP_RNG = new VanillaBuffPropertyMeta<RandomGenerator>("rng");
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("timer");
        public static readonly VanillaBuffPropertyMeta<bool> PROP_OPEN = new VanillaBuffPropertyMeta<bool>("open");
        public static readonly VanillaBuffPropertyMeta<IConveyorPoolPatch[]> PROP_CONVEYOR_POOL_PATCHES = new VanillaBuffPropertyMeta<IConveyorPoolPatch[]>("conveyor_pool_patches");
        public static readonly IConveyorPoolPatch[] openConveyorPoolPatches = new IConveyorPoolPatch[]
        {
            new ConveyorPoolPatchRemoveEntry(LogicBlueprintID.FromEntity(VanillaContraptionID.lilyPad)),
        };
    }
}
